1	import type { Db, ObjectId } from "mongodb";
2	import { ObjectId as ObjectIdCtor } from "mongodb";
3	import { getCollections } from "./collections";
4	import {
5	  buildExtractionPrompt,
6	  type KnownEntity,
7	  type KnownFact,
8	  type LlmFactDraft,
9	  type ParsedExtraction,
10	  parseExtractionResponse,
11	} from "./extraction";
12	import type { UsageContext } from "./gateway";
13	import { deterministicId, insertIgnoringDuplicate } from "./idempotency";
14	import { currentlyValidFilter } from "./schemas/facts";
15	import { proposalSchema } from "./schemas/proposals";
16	import type { Source } from "./schemas/sources";
17	
18	// The extraction worker: source content → LLM → ingestion proposal, feeding
19	// the review queue. Everything the model may reference (anchor ids,
20	// supersedes targets) is validated against the exact context it was shown —
21	// a hallucinated id is a retryable failure, never a proposal.
22	
23	export interface RunExtractionOptions {
24	  /** The LLM call. Injectable so tests and providers stay decoupled. */
25	  generate: (prompt: string, context?: UsageContext) => Promise<string>;
26	  /**
27	   * Reviewer-supplied steer for a re-extraction pass. Threaded straight into
28	   * the prompt — see buildExtractionPrompt's `hint` field comment for why it
29	   * is trusted rather than treated as ingested source content.
30	   */
31	  hint?: string;
32	  /** Failed attempts before the source flips to "failed". Default 3. */
33	  maxAttempts?: number;
34	  sourceId: ObjectId;
35	}
