      {
        $set: {
          "entityDrafts.$[draft].resolution.status": "discarded",
          updatedAt: writtenAt,
        },
      },
      { arrayFilters: [{ "draft.draftId": draftId }] }
    );
  }

  const createdFactIds: ObjectId[] = [];
  for (const { decision, draft, factDoc, factId } of planned.factWrites) {
