// Supersession targets must exist and be unclaimed — checked before the first
// write, like all other validation. A target already superseded by the same
// deterministic factId is a crashed run resuming, so it passes; superseded by
// anything else means another resolution won and this batch must not proceed.
const validateSupersessions = async (
  facts: Collection<Fact>,
  tenantId: string,
  factWrites: PlannedFact[]
): Promise<void> => {
  const claims = new Map<string, { factId: ObjectId; index: number }>();
  for (const { decision, draft, factId } of factWrites) {
    for (const target of draft.supersedes ?? []) {
      const hex = target.toHexString();
      const prior = claims.get(hex);
      if (prior && !prior.factId.equals(factId)) {
        throw new Error(
          `factDrafts[${prior.index}] and factDrafts[${decision.index}] both supersede fact ${hex}`
        );
      }
      claims.set(hex, { factId, index: decision.index });
    }
  }
  if (claims.size === 0) {
    return;
  }
  const targetIds = [...claims.keys()].map((hex) => new ObjectId(hex));
  const found = await facts
    .find({ _id: { $in: targetIds }, tenantId })
    .toArray();
  const foundByHex = new Map(
    found.map((fact) => [fact._id.toHexString(), fact])
  );
  for (const [hex, claim] of claims) {
    const target = foundByHex.get(hex);
    if (!target) {
      throw new Error(
        `factDrafts[${claim.index}] supersedes fact ${hex}, which was not found`
      );
    }
    if (target.supersededBy && !target.supersededBy.equals(claim.factId)) {
      throw new Error(
        `factDrafts[${claim.index}] supersedes fact ${hex}, which is already superseded by ${target.supersededBy.toHexString()}`
      );
    }
  }
};

// Event time is sourced from documents the planner does not otherwise read,
// so it is gathered up front in one pass rather than making planning async.
interface EventTimeContext {
  /** validFrom of every fact a draft may supersede, keyed by hex id. */
  parentValidFrom: Map<string, Date>;
  /** validFrom for facts extracted from this proposal's source. */
  sourceOccurredAt?: Date;
}

const loadEventTime = async (
  collections: ReturnType<typeof getCollections>,
  tenantId: string,
  proposal: Proposal
): Promise<EventTimeContext> => {
  const parentIds = proposal.factDrafts.flatMap(
    (draft) => draft.supersedes ?? []
  );
  const [source, parents] = await Promise.all([
    proposal.sourceId
      ? collections.sources.findOne({ _id: proposal.sourceId, tenantId })
      : null,
    parentIds.length > 0
      ? collections.facts.find({ _id: { $in: parentIds }, tenantId }).toArray()
      : [],
  ]);

  const parentValidFrom = new Map<string, Date>();
  for (const parent of parents) {
    if (parent.validFrom) {
      parentValidFrom.set(parent._id.toHexString(), parent.validFrom);
    }
  }
  return { parentValidFrom, sourceOccurredAt: source?.occurredAt ?? undefined };
};

// Consolidation and contradiction drafts are both derived from existing facts
// they supersede, so their provenance is derivedFrom rather than a sourceId.
const derivesFromFacts = (kind: Proposal["kind"]): boolean =>
  kind === "consolidation" || kind === "contradiction";

// A merge restates its parents, so it has held since the earliest of them did.
const earliestParentValidFrom = (
  supersedes: ObjectId[],
  parentValidFrom: Map<string, Date>
): Date | undefined => {
  let earliest: Date | undefined;
  for (const id of supersedes) {
    const candidate = parentValidFrom.get(id.toHexString());
    if (candidate && (!earliest || candidate < earliest)) {
      earliest = candidate;
    }
  }
  return earliest;
};

const entityCollectionFor = (
  collections: ReturnType<typeof getCollections>,
  draft: EntityDraft
): Collection<Document> => {
  switch (draft.entityType) {
    case "engagement":
      return collections.engagements as unknown as Collection<Document>;
    case "organization":
      return collections.organizations as unknown as Collection<Document>;
    default:
      return collections.people as unknown as Collection<Document>;
  }
};

