    const parsed = inputSchema.safeParse({ ...draft.data, ...decision.data });
    if (!parsed.success) {
      throw new Error(
        `Entity draft "${decision.draftId}" does not satisfy the ${draft.entityType} schema: ${parsed.error.message}`
      );
    }
    confirms.push({
      decision,
      doc: {
        ...parsed.data,
        _id: entityId,
        createdAt: new Date(),
        tenantId: proposal.tenantId,
        updatedAt: new Date(),
      },
      draft,
      entityId,
