"use server";

import { auth } from "@repo/auth/server";
import {
  getCollections,
  ObjectId,
  refreshDossier,
  resolveProposalItems,
} from "@repo/knowledge";
import { getKnowledgeDb } from "@repo/knowledge/client";
import { revalidatePath } from "next/cache";
import {
  buildResolveInput,
  collectDossierAnchors,
  type ReviewSelections,
} from "@/lib/review-decisions";

export interface ResolveResult {
  createdFactCount: number;
  error?: string;
  proposalResolved: boolean;
}

export const resolveProposal = async (
  proposalId: string,
  selections: ReviewSelections,
  originalFactTexts: Record<number, string>
): Promise<ResolveResult> => {
  const { orgId, userId } = await auth();
  if (!(orgId && userId)) {
    return {
      createdFactCount: 0,
      error: "Not signed in to an organization",
      proposalResolved: false,
    };
  }

  const db = getKnowledgeDb();
  const input = buildResolveInput(selections, originalFactTexts);
  const objectId = new ObjectId(proposalId);

  try {
    // resolveProposalItems treats "resolved" as a safe no-op (crash-resume:
    // re-running the same decisions on an already-fully-resolved proposal is
    // deliberately idempotent, see review.ts). "superseded" is different — a
    // re-extraction replaced this proposal with a new generation, so acting
    // on it here would silently do nothing while still reporting success.
    // Caught here, at the same layer I2's re-extract guard lives in, rather
    // than inside resolveProposalItems itself, so the documented idempotent-
    // resume behaviour for "resolved" stays intact for every caller.
    const proposal = await getCollections(db).proposals.findOne({
      _id: objectId,
      tenantId: orgId,
    });
    if (proposal?.status === "superseded") {
      return {
        createdFactCount: 0,
        error:
          "This proposal has been superseded — open the current one from the review queue.",
        proposalResolved: false,
      };
    }

    const result = await resolveProposalItems(db, orgId, {
      entities: input.entities,
      facts: input.facts,
      proposalId: objectId,
      resolvedBy: userId,
    });

    // Keep the always-loadable tier current: refresh the dossier of every
    // anchor that just gained a fact.
    if (result.createdFactIds.length > 0) {
      const { facts } = getCollections(db);
      const created = await facts
        .find({ _id: { $in: result.createdFactIds }, tenantId: orgId })
        .toArray();
      for (const anchor of collectDossierAnchors(created)) {
        // biome-ignore lint/performance/noAwaitInLoops: a handful of anchors per review; sequential keeps it simple
        await refreshDossier(db, orgId, anchor);
      }
    }

    revalidatePath("/review");
    revalidatePath(`/review/${proposalId}`);
    return {
      createdFactCount: result.createdFactIds.length,
      proposalResolved: result.proposalResolved,
    };
  } catch (error) {
    return {
      createdFactCount: 0,
      error: error instanceof Error ? error.message : "Resolution failed",
      proposalResolved: false,
    };
  }
};

"use client";

import { OrganizationSwitcher, UserButton } from "@repo/auth/client";
import { ModeToggle } from "@repo/design-system/components/mode-toggle";
import { Button } from "@repo/design-system/components/ui/button";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from "@repo/design-system/components/ui/sidebar";
import { cn } from "@repo/design-system/lib/utils";
import { NotificationsTrigger } from "@repo/notifications/components/trigger";
import {
  AnchorIcon,
  BrainIcon,
  type LucideIcon,
  NewspaperIcon,
  UsersIcon,
} from "lucide-react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import type { ReactNode } from "react";

interface GlobalSidebarProperties {
  readonly children: ReactNode;
}

interface NavItem {
  icon: LucideIcon;
  title: string;
  url: string;
}

const navMain: NavItem[] = [
  {
    icon: BrainIcon,
    title: "Brain",
    url: "/",
  },
  {
    icon: UsersIcon,
    title: "Team",
    url: "/team",
  },
  {
    icon: NewspaperIcon,
    title: "Digest",
    url: "/digest",
  },
];

const navSecondary: NavItem[] = [
  {
    icon: AnchorIcon,
    title: "Webhooks",
    url: "/webhooks",
  },
];

// Review pages belong to the brain workspace, so they keep its entry lit.
const isActiveUrl = (url: string, pathname: string): boolean =>
  url === "/"
    ? pathname === "/" || pathname.startsWith("/review")
    : pathname.startsWith(url);

const NavMenu = ({ items }: { items: NavItem[] }) => {
  const pathname = usePathname();

  return (
    <SidebarMenu>
      {items.map((item) => (
        <SidebarMenuItem key={item.title}>
          <SidebarMenuButton
            asChild
            isActive={isActiveUrl(item.url, pathname)}
            tooltip={item.title}
          >
            <Link href={item.url}>
              <item.icon />
              <span>{item.title}</span>
            </Link>
          </SidebarMenuButton>
        </SidebarMenuItem>
      ))}
    </SidebarMenu>
  );
};

export const GlobalSidebar = ({ children }: GlobalSidebarProperties) => {
  const sidebar = useSidebar();

  return (
    <>
      <Sidebar variant="inset">
        <SidebarHeader>
          <SidebarMenu>
            <SidebarMenuItem>
              {/* No overflow clipping here: the switcher's popover is
                  absolutely positioned and would be cut off. */}
              <div
                className={cn(
                  "h-[36px] transition-all [&>div]:w-full",
                  sidebar.open ? "" : "-mx-1"
                )}
              >
                <OrganizationSwitcher
                  afterSelectOrganizationUrl="/"
                  hidePersonal
                />
              </div>
            </SidebarMenuItem>
          </SidebarMenu>
        </SidebarHeader>
        <SidebarContent>
          <SidebarGroup>
            <NavMenu items={navMain} />
          </SidebarGroup>
          <SidebarGroup className="mt-auto">
            <SidebarGroupContent>
              <NavMenu items={navSecondary} />
            </SidebarGroupContent>
          </SidebarGroup>
        </SidebarContent>
        <SidebarFooter>
          <SidebarMenu>
            <SidebarMenuItem className="flex items-center gap-2">
              <UserButton
                appearance={{
                  elements: {
                    rootBox: "flex overflow-hidden w-full",
                    userButtonBox: "flex-row-reverse",
                    userButtonOuterIdentifier: "truncate pl-0",
                  },
                }}
                showName
              />
              <div className="flex shrink-0 items-center gap-px">
                <ModeToggle />
                <Button
                  asChild
                  className="shrink-0"
                  size="icon"
