  {
    icon: ClipboardCheckIcon,
    title: "Review",
    url: "/review",
  },
  {
    icon: UsersIcon,
    title: "Team",
    url: "/team",
  },
  {
    icon: NewspaperIcon,
    title: "Digest",
    url: "/digest",
  },
];

const navSecondary: NavItem[] = [
  {
    icon: AnchorIcon,
    title: "Webhooks",
    url: "/webhooks",
  },
